const normalizeArabic = (value = "") =>
  String(value)
    .toLowerCase()
    .replace(/[أإآ]/g, "ا")
    .replace(/ى/g, "ي")
    .replace(/ة/g, "ه")
    .replace(/ؤ/g, "و")
    .replace(/ئ/g, "ي")
    .replace(/[ًٌٍَُِّْـ]/g, "")
    .trim();

const serviceAliases = {
  "pubg": ["pubg", "بوبجي", "ببجي", "شدات"],
  "free fire": ["free fire", "فري فاير", "جواهر"],
  "mobile legends": ["mobile legends", "موبايل ليجند", "ليجند"],
  "roblox": ["roblox", "روبلوكس"],
  "genshin": ["genshin", "جينشن", "جينشين"],
  "steam": ["steam", "ستيم"],
  "playstation": ["playstation", "بلاي ستيشن", "بلايستيشن"],
  "itunes": ["itunes", "ايتونز", "آيتونز"],
  "razer": ["razer", "رايزر"],
  "yemen mobile": ["يمن موبايل", "يمنموبايل"],
  "mtn": ["mtn", "يو", "you"],
  "سبافون": ["سبافون", "saba", "سبا فون"],
  "واي": ["واي", "y telecom", "واي موبايل"],
  "يمن نت": ["يمن نت", "adsl", "انترنت ثابت"],
  "عدن نت": ["عدن نت"],
  "يمن فورجي": ["يمن فورجي", "4g", "فورجي"]
};

function getQueryTokens(message) {
  const normalizedMessage = normalizeArabic(message);
  const tokens = new Set(normalizedMessage.split(/\s+/).filter((word) => word.length >= 2));

  for (const aliases of Object.values(serviceAliases)) {
    if (aliases.some((alias) => normalizedMessage.includes(normalizeArabic(alias)))) {
      aliases.forEach((alias) => tokens.add(normalizeArabic(alias)));
    }
  }

  return [...tokens];
}

export function getRelevantServices(message = "", maxSections = 5, maxItemsPerSection = 18) {
  const normalizedMessage = normalizeArabic(message);
  const tokens = getQueryTokens(message);

  if (!normalizedMessage || !tokens.length) {
    return "";
  }

  const matchedSections = [];

  for (const section of AMD_PAY_SERVICES_DATA) {
    const sectionText = normalizeArabic([
      section.section,
      ...section.items.slice(0, 80).map((item) => Object.values(item).join(" "))
    ].join(" "));

    const sectionMatches = tokens.some((token) => sectionText.includes(token));
    if (!sectionMatches) continue;

    const matchedItems = section.items.filter((item) => {
      const itemText = normalizeArabic(Object.values(item).join(" "));
      return tokens.some((token) => itemText.includes(token));
    });

    matchedSections.push({
      section: section.section,
      headers: section.headers,
      items: (matchedItems.length ? matchedItems : section.items).slice(0, maxItemsPerSection)
    });

    if (matchedSections.length >= maxSections) break;
  }

  if (!matchedSections.length) return "";

  return `
معلومات خدمات وأسعار مرتبطة بسؤال المستخدم:
${matchedSections
    .map((section) => {
      const rows = section.items
        .map((item) => "- " + Object.entries(item).map(([key, value]) => `${key}: ${value}`).join(" | "))
        .join("\n");
      return `\n[${section.section}]\n${rows}`;
    })
    .join("\n")}

تنبيه مهم للبوت: الأسعار قد تتغير، لذلك إذا لم تكن الإجابة مؤكدة أو كان السؤال عن السعر النهائي، قل إن السعر النهائي يظهر داخل التطبيق قبل تأكيد الطلب.
`;
}
